head.script:
scwin.screenId = "jldinf30000";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "if_result", fn: function(){ return (!(String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "result" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("result"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "result" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("result")))).length === 0)); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_searchWord", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("searchWord"))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        const pageIndex = "" + dma_page.get("currentPage") + "";
        const pageObj = $('.paging td:contains(' + pageIndex + ')');
        const pagingLeng = $('.paging td:contains(' + pageIndex + ')').length;
        for (let i = 0; i < pagingLeng; i++) {
            const obj = pageObj[i];
            const val = $(obj).text();
            if (pageIndex !== val) {
                continue;
            }
            const font = "<font color='blue'>" + val + "</font>";
            $(obj).html(font);
            $(obj).attr("style", "font-size:15px;");
        }
        if ((String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "goView" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("goView"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "goView" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("goView")))).indexOf('$' + '{') >= 0 ? '' : String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "goView" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("goView"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "goView" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("goView"))))) !== '') {
            await scwin.goView((String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "goView" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("goView"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "goView" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("goView")))).indexOf('$' + '{') >= 0 ? '' : String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "goView" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("goView"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "goView" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("goView"))))));
        }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf30000.onpageload' }); }
};

// [A] 초기 목록 미해결 — 진입 근거가 다른 액션을 가리킨다(notice vs noticedownload) — 어느 쪽인지 정할 근거가 없다


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.dmenus = undefined; try { scwin.dmenus = /* sdd-asis-lifecycle:begin dmenus — as-is 원문 본문(전환 이관 · 포팅 적용됨) */{
        "bmenu":5
        ,"mmenu":1
    }/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldinf30000' }); }

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_conds();
        await scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldinf30000.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.ipt_searchWord_onkeyup
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.ipt_searchWord_onkeyup = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin ipt_searchWord_onkeyup — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        if(event.keyCode == 13) { await scwin.goSearch(); };fn_boardCheck(selfVar)
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf30000.ipt_searchWord_onkeyup' }); }
};

/**
 * @event
 * @name scwin.btn_goSearch_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_goSearch_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_goSearch_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.goSearch()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf30000.btn_goSearch_onclick' }); }
};

/**
 * @event
 * @name scwin.grd_result_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_result_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_result');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_result'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; } /* 수동 전환 필요: downloadFile (조건 미해석) */
        if (columnId === "__rowAct") { if (typeof scwin.goView === 'function') { await scwin.goView(r["contnId"]); } else { console.error('[sdd] 행 동작 미정의: scwin.goView (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.goView'); } return; } 
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_result.oncellclick' });
    }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_goSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_goSearch = async function () {
    const sbmOptions = {
        id: "tx_goSearch",
        method: "post",
        action: "/info/notice.do?method=noticeList",
        ref: "dma_goSearchReq",
        target: "dlt_result=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldinf30000.tx_goSearch" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

