/**
 * @method
 * @name scwin.goView
 * @author Inswave
 * @date 2026. 09. 29
 * @param id
 * @returns
 * @hidden N
*/
scwin.goView = async function (id) {
    /* sdd-asis-lifecycle:begin goView — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.JLDINF30000 || { elements: [] });
    $c.util.getComponent('dma_goSearchReq').set('contnId', id);
    frm.action = "/info/notice.do?method=noticeView";
    await scwin.tx_goView();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.downloadFile
 * @author Inswave
 * @date 2026. 09. 29
 * @param contn_id attach_file_no
 * @returns
 * @hidden N
*/
scwin.downloadFile = async function (contn_id, attach_file_no) {
    /* sdd-asis-lifecycle:begin downloadFile — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const obj = (document.downloadForm || { elements: [] });
    obj.action = '/info/noticeDownload.do';
    $c.util.getComponent('dma_goSearchReq').set('method', 'noticeDownload');
    $c.util.getComponent("dma_goSearchReq").set("contnId", contn_id);
    $c.util.getComponent("dma_goSearchReq").set("attachFileNo", attach_file_no);
    await scwin.tx_downloadFile();
    /* sdd-asis-lifecycle:end */
};



/**
 * @event
 * @name scwin.krxpage_pagenavigator_80_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param index
 * @returns
 * @hidden N
*/
scwin.krxpage_pagenavigator_80_onclick = function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_goSearchReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_80.page' }); } scwin.goSearch2(); };
